<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Outbox\Domain\Gateway;

use Civi\Lughauth\Features\Notification\Outbox\Domain\Model\OutboundMail;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\SmtpOutboundConfig;

/**
 * Port for sending outbound email messages.
 *
 * Implementations delegate to the infrastructure mail layer (PHPMailer).
 */
interface SmtpMailSenderGateway
{
    /**
     * Sends a mail using the default (globally configured) SMTP settings from app config.
     */
    public function send(OutboundMail $mail): void;

    /**
     * Sends a mail using a tenant-specific SMTP configuration override.
     */
    public function sendWithConfig(SmtpOutboundConfig $config, OutboundMail $mail): void;
}
